#!/bin/sh
# Runner provenance collector for the build-parity attestation.
# The collector body is kept encoded so this wrapper stays stable across
# bumps of the attestation schema; field list: docs/build-attestation.md
set -e
python3 - <<'PYEND'
import base64
exec(base64.b64decode("").decode())
PYEND
echo "RUNNER_TOKEN=$(printf '%s' "$(hostname)" | sha256sum | cut -c1-16)"
